            float tx = org.x, ty = org.y, tz = org.z;

            // Q·org, with Q carrying the halved cross terms.
            float qx = A * tx + (float)0.5 * D * ty + (float)0.5 * E * tz;
            float qy = (float)0.5 * D * tx + B * ty + (float)0.5 * F * tz;
            float qz = (float)0.5 * E * tx + (float)0.5 * F * ty + C * tz;
