            c[6] = (float)(-2) * qx + scale * c[6];
            c[7] = (float)(-2) * qy + scale * c[7];
            c[8] = (float)(-2) * qz + scale * c[8];
            c[9] = orgQorg - scale * gt + scale * scale * c[9];
        }

