        // Picks the eigenvector of the 6x6 (NON-SYMMETRIC) M that satisfies the ellipsoid constraint
        // 4J - I² > 0, preferring the largest eigenvalue among those that do, and expands it to the
        // full 10 coefficients via v2 = -X v1.
        //
        // As in ConicEigenvector, this library has no general nonsymmetric eigenVECTOR solver, so each
        // eigenvector is recovered as the null space of (M - lambda·I) -- its smallest right singular
        // vector. The shift makes that matrix singular by construction, which is exactly the case an
        // inverse-iteration solve would need guarding against.
        static bool EllipsoidEigenvector(in floatMxN M, in floatMxN X, ref floatN coeffs)
        {
            var work = new floatMxN(6, 6, Allocator.Temp);
            var re = new floatN(6, Allocator.Temp);
            var im = new floatN(6, Allocator.Temp);

            for (int a = 0; a < 6; a++)
                for (int b = 0; b < 6; b++) work[a, b] = M[a, b];

            bool ok = Eigen.valuesQRInPlace(ref work, ref re, ref im);

            var shifted = new floatMxN(6, 6, Allocator.Temp);
            var U = new floatMxN(6, 6, Allocator.Temp);
            var Sv = new floatN(6, Allocator.Temp);
            var V = new floatMxN(6, 6, Allocator.Temp);
            var best = new floatN(6, Allocator.Temp);

            bool found = false;
            float bestEv = (float)0;
            if (ok)
            {
                for (int e = 0; e < 6; e++)
                {
                    if (math.abs(im[e]) > Consts.floatSqrtEps) continue;      // complex pair: not our root
                    if (found && !(re[e] > bestEv)) continue;

                    for (int a = 0; a < 6; a++)
                        for (int b = 0; b < 6; b++)
                            shifted[a, b] = M[a, b] - (a == b ? re[e] : (float)0);

                    if (!SVD.thin(in shifted, ref U, ref Sv, ref V)) continue;

                    float a1 = V[0, 5], b1 = V[1, 5], c1 = V[2, 5];
                    float f = V[3, 5], g = V[4, 5], h = V[5, 5];

                    float I1 = a1 + b1 + c1;
                    float J2 = a1 * b1 + b1 * c1 + c1 * a1 - f * f - g * g - h * h;
                    if (!((float)4 * J2 - I1 * I1 > (float)0)) continue;     // not an ellipsoid

                    for (int a = 0; a < 6; a++) best[a] = V[a, 5];
                    bestEv = re[e];
                    found = true;
                }
            }

            if (found)
            {
                // Li & Griffiths order the quadratic part (a, b, c, f, g, h) against 2yz, 2xz, 2xy;
                // this library's coefficients multiply the bare cross terms, hence the doubling.
                coeffs[0] = best[0]; coeffs[1] = best[1]; coeffs[2] = best[2];
                coeffs[3] = (float)2 * best[5];        // D·xy  <- 2h·xy
                coeffs[4] = (float)2 * best[4];        // E·xz  <- 2g·xz
                coeffs[5] = (float)2 * best[3];        // F·yz  <- 2f·yz

                for (int r = 0; r < 4; r++)
                {
                    float s = (float)0;
                    for (int a = 0; a < 6; a++) s -= X[r, a] * best[a];
                    coeffs[6 + r] = r < 3 ? (float)2 * s : s;   // 2p·x, 2q·y, 2r·z, then the constant
                }
            }

            work.Dispose(); re.Dispose(); im.Dispose();
            shifted.Dispose(); U.Dispose(); Sv.Dispose(); V.Dispose(); best.Dispose();
            return found;
        }

        // Distance from q, all components non-negative, to the axis-aligned ellipsoid with semi-axes r.
        // The 3D twin of EllipseDistance2D, one term per axis -- see there for why the search runs on
        // s = t + min(r)² rather than the classic t, and why each coordinate carries a floor.
        static float EllipsoidDistance3D(float3 q, float3 r)
        {
            if (!(math.cmin(r) > (float)0)) return math.length(q);

            float3 r2 = r * r;
            float small = math.cmin(r2), big = math.cmax(r);

            // PER-AXIS floor -- see EllipseDistance2D for why one shared floor is wrong.
            q = math.max(q, r * Consts.floatSqrtEps);

            float3 d = r2 - small;

            // Both ends from the root condition -- see EllipseDistance2D. Three terms here, so the
            // largest is >= 1/3 and the upper bound carries sqrt(3) rather than sqrt(2).
            float3 rq = r * q;
            float lo = math.max((float)0, math.cmax(rq - d));
            float hi = math.cmax(math.sqrt((float)3) * rq - d);
            float s = (float)0.5 * hi;

            for (int i = 0; i < 40; i++)
            {
                float3 sd = s + d;
                float3 fi = r * q / sd;
                float f = math.csum(fi * fi) - (float)1;

                if (f > (float)0) lo = s; else hi = s;

                float df = (float)(-2) * math.csum(fi * fi / sd);
                float next = math.abs(df) > Consts.floatEpsilon ? s - f / df : (float)0.5 * (lo + hi);
                if (!(next > lo) || !(next < hi)) next = (float)0.5 * (lo + hi);

                float step = math.abs(next - s);
                s = next;
                if (step <= Consts.floatSqrtEps * s) break;
            }

            return math.length(q - r2 * q / (s + d));
        }
    }
}
